// EconomicsInputsOut Echo of what fed the model, with provenance so the UI can label it.
//
// The “*_source“ fields are “fact“ (pulled from financial facts / payroll)
// or “manual“ (owner-entered target). Dividends and outsourcing are always
// “manual“. “personnel_cost“ = “personnel_staff“ (loaded штатный payroll)
// + “outsourcing“, unless a full manual “personnel_cost“ override is given.
type EconomicsInputsOut struct {
	DateFrom  openapi_types.Date `json:"date_from"`
	DateTo    openapi_types.Date `json:"date_to"`
	Dividends float32            `json:"dividends"`

	// DividendsSource manual
	DividendsSource string  `json:"dividends_source"`
	Outsourcing     float32 `json:"outsourcing"`

	// OutsourcingSource manual
	OutsourcingSource string  `json:"outsourcing_source"`
	OverheadCost      float32 `json:"overhead_cost"`

	// OverheadSource fact | plan | manual
	OverheadSource string  `json:"overhead_source"`
	PersonnelCost  float32 `json:"personnel_cost"`

	// PersonnelSource fact | manual
	PersonnelSource string  `json:"personnel_source"`
	PersonnelStaff  float32 `json:"personnel_staff"`
}

// EconomicsModelOut Full report: input echo, shared payroll block, and per-scenario columns.
//
// “debug“ carries formula traces for developer mode; present only when
// requested and the user is a developer.
type EconomicsModelOut struct {
	Debug nullable.Nullable[[]TraceEntry] `json:"debug,omitempty"`

	// Inputs Echo of what fed the model, with provenance so the UI can label it.
	//
	// The ``*_source`` fields are ``fact`` (pulled from financial facts / payroll)
	// or ``manual`` (owner-entered target). Dividends and outsourcing are always
	// ``manual``. ``personnel_cost`` = ``personnel_staff`` (loaded штатный payroll)
	// + ``outsourcing``, unless a full manual ``personnel_cost`` override is given.
	Inputs EconomicsInputsOut `json:"inputs"`

	// Payroll Company-level штатный payroll block (shared across scenarios).
	//
	// ``ndfl_mode`` is ``progressive`` when derived from the app's real payroll
	// engine, ``flat`` when using the spreadsheet's simplified rate. ``source`` is
	// ``fact`` or ``manual``.
	Payroll   EconomicsPayrollOut    `json:"payroll"`
	Scenarios []EconomicsScenarioOut `json:"scenarios"`
}

// EconomicsPayrollOut Company-level штатный payroll block (shared across scenarios).
